const GREEN_FIELD: SourcePoint[][] = BLUE_FIELD.map((rank) => rank.map(({ x, y }) => ({ x: 1280 - x, y })));

export const SOURCE_NODES: Record<SanguoFaction, SourcePoint[][]> = {
  red: RED_FIELD,
  blue: BLUE_FIELD,
  green: GREEN_FIELD,
};

export const fieldPoint = (sector: SanguoFaction, rank: number, file: number) => SOURCE_NODES[sector][rank][file];
export const fieldPolyline = (points: SourcePoint[]) => points.map((point) => `${point.x},${point.y}`).join(" ");

