export const palaceConnections = (sector: SanguoFaction): Array<[SourcePoint, SourcePoint]> => {
  const pattern = sector === "red" ? [[2, 3, 4, 5], [2, 5, 4, 3]] : [[1, 3, 3, 5], [1, 5, 3, 3]];
  return pattern.map(([fromRank, fromFile, toRank, toFile]) => [fieldPoint(sector, fromRank, fromFile), fieldPoint(sector, toRank, toFile)]);
};
